/bin/bash -lc "node --input-type=module <<'EOF'
import { priceFor } from './src/pricing.js';
import { formatMoney, parseDate, chunk, retry } from './src/util.js';
const cases = [
  ['missing order fields', () => priceFor({})],
  ['negative quantity', () => priceFor({quantity: -1, date: '2026-09-02'})],
  ['fractional quantity', () => priceFor({quantity: 1.5, date: '2026-09-02'})],
  ['invalid date', () => priceFor({quantity: 1, date: 'not-a-date'})],
  ['negative money', () => formatMoney(-1)],
  ['zero chunk size', () => chunk([1, 2], 0)],
  ['retry zero times', () => retry(() => 1, 0)],
];
for (const [name, fn] of cases) {
  try { console.log(name, '=>', fn()); } catch (e) { console.log(name, 'throws', e.constructor.name, e.message); }
}
console.log('date parse', parseDate('2026-02-31'));
EOF"
